if (worldAngle || planAngle) {
  const rot2 = pt => geo.rotatePoint(pt, worldAngle + planAngle, rcx, rcy);
  pts.forEach(p => { const r = rot2(p); p.x = r.x; p.y = r.y; });
  rooms.forEach(r => {
    if (r.polygon) r.polygon = r.polygon.map(rot2);
    if (r.label) r.label = rot2(r.label);
  });
}
